module decomposition_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [4:0] exp0, exp1, exp2, exp3, exp4, exp5, exp6, exp7, exp8, exp9, exp10,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // Parameters\n    localparam [31:0] MOD = 1000000007;\n    localparam [3:0] MAX_PRIMES = 4'd11;\n    \n    // State encoding\n    localparam [2:0] IDLE              = 3'd0;\n    localparam [2:0] COMPUTE_BINOM     = 3'd1;\n    localparam [2:0] NUMERATOR_LOOP    = 3'd2;\n    localparam [2:0] MULTIPLY_NUM      = 3'd3;\n    localparam [2:0] MULT_INV_FACT     = 3'd4;\n    localparam [2:0] ACCUM_RESULT      = 3'd5;\n    localparam [2:0] UPDATE_RESULT     = 3'd6;\n    localparam [2:0] DONE_STATE        = 3'd7;\n\n    // Registers\n    reg [2:0] state, next_state;\n    reg [3:0] n_reg;\n    reg [4:0] exp_reg [0:10];  // 11 primes\n    reg [31:0] numerator;\n    reg [31:0] binom;\n    reg [4:0] prime_idx;\n    reg [3:0] loop_i;\n    reg [31:0] mul_a_reg;\n    reg [31:0] mul_b_reg;\n    reg [31:0] mul_result;\n    reg [5:0] mul_counter;\n    wire mul_done = (mul_counter == 6'd0);\n\n    // Inverse factorial LUT (for (n-1)!^{-1} mod MOD)\n    wire [31:0] inv_fact [0:7];\n    assign inv_fact[0] = 32'd1;          // inv(0!)\n    assign inv_fact[1] = 32'd1;          // inv(1!)\n    assign inv_fact[2] = 32'd500000004;  // inv(2!)\n    assign inv_fact[3] = 32'd166666668;  // inv(3!)\n    assign inv_fact[4] = 32'd41666667;   // inv(4!)\n    assign inv_fact[5] = 32'd808333337;  // inv(5!)\n    assign inv_fact[6] = 32'd201388893;  // inv(6!)\n    assign inv_fact[7] = 32'd35791429;   // inv(7!)\n\n    // FSM and datapath\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd1;\n            prime_idx <= 5'd0;\n            loop_i <= 4'd0;\n            numerator <= 32'd0;\n            binom <= 32'd0;\n            mul_counter <= 6'd0;\n            mul_result <= 32'd0;\n            // Initialize exp_reg array\n            exp_reg[0] <= 5'd0;\n            exp_reg[1] <= 5'd0;\n            exp_reg[2] <= 5'd0;\n            exp_reg[3] <= 5'd0;\n            exp_reg[4] <= 5'd0;\n            exp_reg[5] <= 5'd0;\n            exp_reg[6] <= 5'd0;\n            exp_reg[7] <= 5'd0;\n            exp_reg[8] <= 5'd0;\n            exp_reg[9] <= 5'd0;\n            exp_reg[10] <= 5'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Store inputs\n                        n_reg <= n;\n                        exp_reg[0] <= exp0;\n                        exp_reg[1] <= exp1;\n                        exp_reg[2] <= exp2;\n                        exp_reg[3] <= exp3;\n                        exp_reg[4] <= exp4;\n                        exp_reg[5] <= exp5;\n                        exp_reg[6] <= exp6;\n                        exp_reg[7] <= exp7;\n                        exp_reg[8] <= exp8;\n                        exp_reg[9] <= exp9;\n                        exp_reg[10] <= exp10;\n                        result <= 32'd1;\n                        prime_idx <= 5'd0;\n                        state <= COMPUTE_BINOM;\n                    end\n                end\n\n                COMPUTE_BINOM: begin\n                    if (prime_idx < MAX_PRIMES) begin\n                        if (exp_reg[prime_idx] > 5'd0) begin\n                            numerator <= 32'd1;\n                            loop_i <= 4'd1;\n                            state <= NUMERATOR_LOOP;\n                        end else begin\n                            prime_idx <= prime_idx + 5'd1;\n                        end\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                NUMERATOR_LOOP: begin\n                    if (loop_i < n_reg) begin\n                        // Start multiplication: numerator = numerator * (exp_reg[prime_idx] + loop_i)\n                        mul_a_reg <= numerator;\n                        mul_b_reg <= exp_reg[prime_idx] + loop_i;\n                        mul_counter <= 6'd32;\n                        state <= MULTIPLY_NUM;\n                    end else begin\n                        // Multiply by inverse factorial\n                        mul_a_reg <= numerator;\n                        mul_b_reg <= inv_fact[n_reg - 4'd1];\n                        mul_counter <= 6'd32;\n                        state <= MULT_INV_FACT;\n                    end\n                end\n\n                MULTIPLY_NUM: begin\n                    if (!mul_done) begin\n                        // Shift-add multiplier\n                        if (mul_b_reg[0]) begin\n                            mul_result <= (mul_result + mul_a_reg >= MOD) ? \n                                         (mul_result + mul_a_reg - MOD) : \n                                         (mul_result + mul_a_reg);\n                        end\n                        mul_a_reg <= {mul_a_reg[30:0], 1'b0};\n                        if (mul_a_reg >= MOD) mul_a_reg <= mul_a_reg - MOD;\n                        mul_b_reg <= mul_b_reg >> 1;\n                        mul_counter <= mul_counter - 6'd1;\n                    end else begin\n                        numerator <= mul_result;\n                        mul_result <= 32'd0;\n                        loop_i <= loop_i + 4'd1;\n                        state <= NUMERATOR_LOOP;\n                    end\n                end\n\n                MULT_INV_FACT: begin\n                    if (!mul_done) begin\n                        // Same shift-add logic\n                        if (mul_b_reg[0]) begin\n                            mul_result <= (mul_result + mul_a_reg >= MOD) ? \n                                         (mul_result + mul_a_reg - MOD) : \n                                         (mul_result + mul_a_reg);\n                        end\n                        mul_a_reg <= {mul_a_reg[30:0], 1'b0};\n                        if (mul_a_reg >= MOD) mul_a_reg <= mul_a_reg - MOD;\n                        mul_b_reg <= mul_b_reg >> 1;\n                        mul_counter <= mul_counter - 6'd1;\n                    end else begin\n                        binom <= mul_result;\n                        mul_result <= 32'd0;\n                        state <= ACCUM_RESULT;\n                    end\n                end\n\n                ACCUM_RESULT: begin\n                    // Multiply result by binom\n                    mul_a_reg <= result;\n                    mul_b_reg <= binom;\n                    mul_counter <= 6'd32;\n                    state <= UPDATE_RESULT;\n                end\n\n                UPDATE_RESULT: begin\n                    if (!mul_done) begin\n                        // Shift-add multiplier\n                        if (mul_b_reg[0]) begin\n                            mul_result <= (mul_result + mul_a_reg >= MOD) ? \n                                         (mul_result + mul_a_reg - MOD) : \n                                         (mul_result + mul_a_reg);\n                        end\n                        mul_a_reg <= {mul_a_reg[30:0], 1'b0};\n                        if (mul_a_reg >= MOD) mul_a_reg <= mul_a_reg - MOD;\n                        mul_b_reg <= mul_b_reg >> 1;\n                        mul_counter <= mul_counter - 6'd1;\n                    end else begin\n                        result <= mul_result;\n                        mul_result <= 32'd0;\n                        prime_idx <= prime_idx + 5'd1;\n                        state <= COMPUTE_BINOM;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule